/** Current public event copy, supplied 2026-11-02. */
export function createEventPages(ctx) {
  const {t,href,link,arrow,right,eyebrow,sectionLabel,notice,rows,table,faq,article,pageHero,subLayout,taskArt}=ctx;
  const p=(en,zh)=>`<p>${t(en,zh)}</p>`;
  const official=()=>`<a href="https://gaac.gosim.org/" target="_blank" rel="noopener">gaac.gosim.org ${arrow}</a>`;
  const scheduleNotice=()=>notice(t('Registration dates, selection arrangements, the platform calendar, detailed technical rules, and appeals procedures will be announced by the organizing committee.','报名时间、入选安排、上机日历、详细技术规则及申诉程序，由赛事组委会统一公告。'));
  const cta=()=>`<div class="wrap"><section class="cta-section"><div><h2>${t('Registration and<br>cooperation information','报名参赛<br>与合作方式')}</h2><p>${t('Form a team, register as an individual, sponsor shared resources, or bring an enterprise scenario.','队长发起组队，个人自由报名；也欢迎提供赞助资源、企业场景与研究方法。')}</p></div>${link('/involve/',t('Participation & registration','查看参与与报名方式'),'button')}</section></div>`;
  const applications=[
    {id:'ppt',name:t('Editable PPT','可编辑 PPT'),format:'PPTX',input:t('Turn enterprise facts, audience requirements, and layout constraints into a native presentation. Handle charts, complex pages, and specified local edits.','根据企业事实资料、受众与版式要求生成演示稿，完成图表、复杂页面和指定局部修改。'),deliver:t('Native PPTX, previews, source mapping, and edit-verification records.','原生 PPTX、预览、必要的资料对应与编辑验证记录。'),quality:t('Accurate facts and numbers; requirements covered; editable text, graphics and charts; readable layout; unrelated content preserved during local edits.','事实与数字准确、需求覆盖；文字、图形与图表可编辑；版式可读；局部修改保护其他内容。'),accept:t('A person other than the author can open, edit, save, and reopen the file with consistent content and presentation.','非原作者能够打开、修改、保存并重新打开，内容与呈现保持一致。')},
    {id:'finance',name:t('Financial analysis & visualization','财报分析与可视化'),format:'XLSX',input:t('Extract data from shared financial reports. Compare periods or companies, calculate metrics, visualize findings, and identify restatements, inconsistent definitions, and anomalies.','从统一财报中提取数据，完成跨期或跨公司分析、计算与图表，识别口径变化、重述和异常。'),deliver:t('Native XLSX workbook, editable charts, conclusions, and data sources.','原生 XLSX 分析工作簿、可编辑图表、结论摘要和数据来源。'),quality:t('Correct entity, period, currency and units; verifiable formulas; clear comparison basis; conclusions supported by data.','公司、期间、币种与单位正确；公式和计算可复核；比较口径清楚；结论有数据支持。'),accept:t('Independent reviewers can return to sources, recalculate key figures, and confirm the workbook and charts update correctly when data changes.','独立评审能回到来源、复算关键数字，修改数据后工作簿与图表能够正确更新。')},
    {id:'research',name:t('Deep Research','研究报告（Deep Research）'),format:'REPORT',input:t('Search, read, compare, and synthesize supplied material around an enterprise research question. Resolve conflicting sources and produce a reviewable report or decision memo.','围绕企业研究问题，对给定资料检索、阅读、比较与综合，处理来源冲突，形成可审议的研究报告或决策备忘录。'),deliver:t('Report, source index, claim-to-evidence mapping, and clear limitations.','研究报告、来源索引、关键主张与证据对应关系，以及必要的局限说明。'),quality:t('Question coverage; accurate figures and citations; genuine evidential support; conflicts handled; facts, inferences and recommendations distinguished.','问题覆盖、数字和引文准确、证据支持主张、冲突处理，以及事实、推断与建议的清楚区分。'),accept:t('Reviewers can locate and verify key evidence. Missing material is acknowledged. This edition uses a frozen local library.','评审能定位并核对关键证据；资料不足时说明不确定性。本届使用冻结的本地资料库。')}
  ];
  const applicationCards=()=>`<div class="task-grid">${applications.map((a,i)=>`<a class="task-card" href="${href('/challenge/#'+a.id)}"><div class="task-art">${taskArt(i)}</div><span class="micro">0${i+1} / ${a.format}</span><h3>${a.name}</h3><p>${a.input}</p><div class="task-bottom"><span>${t('Required · 25 points','全部必做 · 25 分')}</span>${arrow}</div></a>`).join('')}</div>`;
  const phases=()=>`<div class="phase-grid"><div class="phase"><span class="micro">${t('PHASE 01 / HOURS 0–30','第一阶段 / 0—30 小时')}</span><h3>${t('Foundation & engineering','基础与工程能力')}</h3><p>${t('Build the system and verify deployment, inference, state, scheduling, recovery and evidence. Open book: Codex, Claude Code and mature open-source components may be used.','搭建系统，验证部署、推理、状态、调度、恢复与证据计量。开卷，可使用 Codex、Claude Code 等开发工具和成熟开源组件。')}</p><div class="phase-score">25 <span>${t('formal points','正式分')}</span></div></div><div class="phase accent"><span class="micro">${t('PHASE 02 / HOURS 30–168','第二阶段 / 30—168 小时')}</span><h3>${t('Applications & full-stack delivery','应用与全栈综合考核')}</h3><p>${t('Complete all three applications, each worth 25 points. Formal evaluation uses a sealed version and local DeepSeek or other approved tools. Optional platform optimization runs offline in an isolated copy.','三类应用全部必做，各 25 分。正式评测使用封存版本及本地 DeepSeek 等获准工具；可在隔离副本中离线开展可选平台优化。')}</p><div class="phase-score">75 <span>${t('formal points','正式分')}</span></div></div></div>`;
  const scoringTracks=()=>`<div class="score-tracks"><div class="score-track"><div class="micro">ENGINEERING WITH AGENTS</div><div class="track-number">100<span>${t('formal points','正式分')}</span></div><h3>${t('Use agents to deliver applications','用智能体完成场景')}</h3><p>${t('Phase one: 25. Three required applications: 25 each. Evaluate delivery quality, qualified efficiency, independent reproduction and evidence.','第一阶段 25 分，三类应用各 25 分。评估场景交付质量、质量约束下的效率、独立复现与证据。')}</p></div><div class="score-track bonus"><div class="micro">ENGINEERING AGENTIC SYSTEMS</div><div class="track-number">+20<span>${t('optional bonus, maximum','可选加分上限')}</span></div><h3>${t('Improve the agentic platform itself','优化智能体平台本身')}</h3><p>${t('Reusable platform engineering improvements are assessed separately. One event-wide bonus cap of 20; not 20 per application. Skipping it does not reduce the formal score.','可复用的平台工程改进单独验收。全赛合计最高加 20 分，并非每类应用各加 20 分；不做不扣正式分。')}</p></div></div>`;
  const roadmapRows=()=>rows([
    ['01–30 '+t('days','天'),t('Review open-source outputs, independently reproduce results, collect evaluation issues, and assign reference-package maintainers. Join maintenance, reproduction, and Benchmark task and metric design.','整理审查开源成果、独立复现、汇总评测问题，明确参考方案和维护分工。参与方案维护、复现实验和 Benchmark 任务指标共建。')],
    ['31–60 '+t('days','天'),t('Continue Testbed testing, joint research, white papers and specification drafts, enterprise trials, courses and practical training.','在 Testbed 持续测试，推进联合研究、白皮书与规范草案，开展企业试用、课程与实训。')],
    ['61–90 '+t('days and beyond','天及以后'),t('Advance enterprise pilot acceptance, reference architecture, evaluation and course updates. Connect projects, deployment, integration and ongoing operations.','推进企业试点验收，迭代参考架构、评测与课程；连接企业项目、行业模板、部署集成与持续运营合作。')]
  ]);
  const participantValue=[
    [t('Participants & open-source teams','参赛者与开源团队'),t('Compete for the US$10,000 team grand prize. Build verifiable application and engineering work, then contribute to maintenance, Benchmarks, research, training and matching enterprise projects.','争夺 10,000 美元团队大奖，积累可复核的应用与工程成果。赛后可参与开源维护、Benchmark、研究、培训和匹配的企业项目。')],
    [t('Sponsors & technology partners','赞助商与技术资源伙伴'),t('Contribute funding, compute, storage, networking, tools or engineering. Receive agreed brand visibility, usage and outcome reports, adaptation feedback and technical exchanges.','通过资金、算力、存储网络、工具与工程支持参与，获得约定的品牌展示、使用与成果报告、适配反馈及技术交流。')],
    [t('Enterprise users & scenario partners','企业用户与行业场景伙伴'),t('Define real needs and success criteria, try solutions, participate in independent acceptance, train internal teams, and explore direct enterprise project collaboration.','提出真实需求与成功标准，参与试用和独立验收，通过实操培训建设内部能力，并对接直接企业项目合作。')],
    [t('Universities & research institutions','高校与研究机构'),t('Contribute evaluation methods, joint research, white papers, courses and practical training, according to contribution and partner agreements.','参与评测方法、联合研究、白皮书、课程与实训共建，按实际贡献与合作约定推进。')]
  ];
  const sharedFaq=()=>faq([
    [t('Can I register with application experience or expertise in just one layer?','只有应用经验，或只擅长某一技术层，可以报名吗？'),t('Yes. Individuals can provide their skills, experience and team preferences, find complementary teammates and form a team. Captains can also organize existing collaborators or cross-project teams. Teams may have three or more members, with a named captain and responsibilities.','可以。个人可提交能力、经验与组队意向，寻找互补队友后自由成队；队长也可组织已有协作者或跨项目团队。每队可有三人或更多成员，并明确队长与职责。')],
    [t('Must every team complete all three applications?','三类应用需要全部完成吗？'),t('Yes. Editable PPT, financial analysis and visualization, and Deep Research are all required. Each contributes 25 points to the 75-point second phase.','需要。可编辑 PPT、财报分析与可视化、Deep Research 全部必做，各 25 分，合计第二阶段正式 75 分。')],
    [t('Must every component be built from scratch?','必须从零开发所有组件吗？'),t('No. Mature open-source components may be combined. Teams are assessed on their ability to build and use a working full-stack system, deliver real tasks, and provide verifiable results and evidence.','不必。可以组合成熟开源组件，重点是搭建并使用可运行的全栈系统，完成真实任务，交付可核验的结果和证据。')],
    [t('Which tools are allowed in the two phases?','开卷和正式评测阶段分别可以使用哪些工具？'),t('Phase one is open book and allows development tools such as Codex and Claude Code. Phase-two formal evaluation uses a sealed version and local DeepSeek or other approved tools. Platform optimization uses an isolated copy and uniform offline quotas. Model versions and tool rules will be announced before the event.','第一阶段开卷，可用 Codex、Claude Code 等开发工具。第二阶段正式评测使用封存版本及本地 DeepSeek 等获准工具；平台优化在隔离副本与统一离线资源额度内开展。模型版本和工具规则赛前统一公布。')],
    [t('How does application delivery differ from platform optimization?','用智能体完成应用和优化智能体平台有什么区别？'),t('The formal 100 points assess using agents to deliver the required scenarios. The optional 20-point track assesses reusable engineering improvements to the platform itself. Repairing a single presentation, workbook or report remains scenario delivery. The same quality, token or cost result cannot earn duplicate credit.','正式 100 分评使用智能体完成场景的能力，可选 20 分评平台本身的可复用工程改进。单独修补某份 PPT、工作簿或报告仍属场景交付，同一次质量、Token 或成本成绩不重复加分。')],
    [t('How will competition results and the Benchmark be used afterward?','比赛成绩和 Benchmark 后续如何使用？'),t('Results support reproducible open-source packages and continuing Testbed work. Enterprises, developers and researchers can improve shared application and technical evaluations, white papers, specification proposals, training and project collaboration. Publication respects licenses and data permissions.','成果进入可复现开源参考包与持续 Testbed。企业、开发者和研究者可共同改进应用与技术评测，推进白皮书、规范建议、培训与项目合作；公开发布遵守许可证与数据授权边界。')]
  ]);
  function home(){
    const step=(id,number,title,description,body,open=false)=>`<li><details class="participant-step" id="${id}" open><summary class="guide-step-summary"><span class="guide-step-number" aria-hidden="true">${number}</span><div class="guide-step-label"><h3 class="guide-step-title">${title}</h3><span class="guide-step-description">${description}</span></div><span class="guide-step-toggle" data-open="${t('Read more','展开详情')}" data-close="${t('Collapse','收起详情')}" aria-hidden="true"></span></summary><div class="guide-step-body">${body}</div></details></li>`;
    return `<div class="wrap event-home">
      <section class="event-intro event-intro-compact island-hero" id="about" aria-labelledby="event-title">
        <div class="event-intro-copy">
          ${t('','<p class="event-full-name">Grand Agentic AI Challenge</p>')}
          <h1 id="event-title">${t('Grand Agentic<br>AI Challenge','智能体大奖赛')}</h1>
          <h2 class="event-purpose">${t('Build agents for real business tasks.','用智能体，完成真实企业任务。')}</h2>
          <nav class="event-task-summary hero-task-links" aria-label="${t('Three required applications','三类必做应用')}">${applications.map(a=>`<a href="${href('/challenge/#'+a.id)}">${a.name}</a>`).join('<span aria-hidden="true">·</span>')}</nav>
          <div class="event-intro-actions"><a class="event-scroll-link" href="#participant-guide"><span class="event-down" aria-hidden="true">↓</span><span>${t('Scroll for event details','向下滚动，查看详情')}</span></a>${link('/teams/',t('How to participate','了解参赛方式'),'button')}</div>
        </div>
        <div class="hero-world" data-hero-world data-state="loading">
          <img class="hero-world-cover" src="/assets/hero-islands.webp?v=gaac-campus-20261105" width="1400" height="1050" alt="${t('Three connected application islands with an EdgePod shared compute centre: editable presentations, financial charts and a research library.','由 EdgePod 共享算力中心连接的三座应用岛：可编辑演示稿、财报图表与研究资料馆。')}" fetchpriority="high">
          <canvas aria-hidden="true"></canvas>
          <div class="hero-world-labels" aria-label="${t('Application islands and shared compute','应用岛与共享算力')}">
            <button type="button" class="hero-world-label" data-hero-label data-hero-focus="0" disabled aria-pressed="false" style="--label-x:24%;--label-y:11%">${t('Editable PPT','可编辑 PPT')}</button>
            <button type="button" class="hero-world-label" data-hero-label data-hero-focus="1" disabled aria-pressed="false" style="--label-x:76%;--label-y:12%">${t('Financial analysis','财报分析')}</button>
            <button type="button" class="hero-world-label label-below" data-hero-label data-hero-focus="2" disabled aria-pressed="false" style="--label-x:77%;--label-y:91%">${t('Research reports','研究报告')}</button>
            <button type="button" class="hero-world-label label-below label-compute" data-hero-label data-hero-focus="3" disabled aria-pressed="false" aria-label="${t('EdgePod shared compute','EdgePod 共享算力中心')}" style="--label-x:29%;--label-y:79%"><strong>EdgePod</strong><span>${t('Shared compute','共享算力中心')}</span></button>
          </div>
          <div class="hero-world-controls"><button type="button" data-hero-reset hidden aria-label="${t('Reset world view','恢复小世界全景')}" title="${t('Reset view','恢复全景')}">↶ <span>${t('Overview','全景')}</span></button><button type="button" data-hero-motion hidden aria-label="${t('Pause world animation','暂停小世界动画')}" aria-pressed="false">Ⅱ</button></div>
        </div>
        <aside class="hero-facts" aria-label="${t('Event at a glance','赛事要点')}">
          <span><i class="gaac-icon gi-clock-three" aria-hidden="true"></i><span>${t('Per team','每队')} <strong>168</strong> ${t('hours','小时')}</span></span>
          <span><i class="gaac-icon gi-layers" aria-hidden="true"></i><span><strong>2</strong> ${t('phases · 3 required applications','阶段 · 3 类应用必做')}</span></span>
          <span><i class="gaac-icon gi-trophy" aria-hidden="true"></i><span>${t('1 team grand prize','团队大奖 1 名')} <strong>US$10,000</strong></span></span>
        </aside>
      </section>
      <section class="participant-guide" id="participant-guide" aria-labelledby="guide-title"><div class="guide-intro"><h2 id="guide-title">${t('Participant guide','参赛指南')}</h2></div><div id="liquid-guide" class="liquid-guide-mount"><ol class="participant-timeline">
        ${step('tasks','01',t('What will we build?','比赛要做什么？'),t('Three application tasks. All are required.','三类应用，全部必做。'),`<p>${t('Build your agent system under shared hardware and evaluation conditions. Each application contributes 25 formal points.','在统一硬件与评测条件下搭建智能体系统。每类应用占正式考核 25 分。')}</p>        <ol class="event-task-list">${applications.map((a,i)=>`<li><span class="task-format">${a.format}</span><div><h4>${a.name}</h4><p>${a.input}</p><p class="task-delivery"><strong>${t('Deliver','交付')}</strong>${a.deliver}</p></div>${link('/challenge/#'+a.id,t('Task requirements','查看交付与验收要求'))}</li>`).join('')}</ol>`,false)}
        ${step('eligibility','02',t('Who can participate?','我能参加吗？'),t('Developers, open-source teams and people with industry experience.','欢迎开发者、开源团队与行业实践者。'),`<p>${t('Teammates can cover more than one role or divide responsibilities further. Find collaborators whose skills complement yours.','成员可兼任，也可按能力进一步分工，寻找互补队友。')}</p><ul class="guide-skills">${[[t('Applications & users','应用与场景'),t('Needs, business analysis, artifact quality and user experience.','需求理解、业务分析、交付质量与用户体验。')],[t('Agent engineering','智能体工程'),t('Tool integration, context, memory, orchestration and application workflows.','工具集成、上下文与记忆、任务编排与应用工作流。')],[t('Inference & systems','推理与系统'),t('Model serving, KV state, scheduling, deployment, performance and reliability.','模型服务、KV 状态、资源调度、部署、性能与可靠性。')],[t('Evaluation & delivery','评测与交付'),t('Testing, safety, resource accounting, independent acceptance and maintenance.','测试、安全、资源计量、独立验收与开源维护。')]].map(v=>`<li><strong>${v[0]}</strong><span>${v[1]}</span></li>`).join('')}</ul><p class="guide-eligibility-note">${t('Teams have three or more members, with a named captain and agreed responsibilities. The first edition plans to select five teams. Registration review and final team confirmation follow committee announcements.','每队 3 人或以上，指定队长并说明职责。首届计划遴选 5 队，报名审核与正式组队确认安排由组委会公布。')}</p>${link('/teams/',t('More about team capabilities','了解队伍能力与分工'))}`,false)}
        ${step('registration','03',t('How do I register and find teammates?','怎么报名和组队？'),t('Registration and team formation are coming soon.','报名与组队稍后开始。'),`        <div class="event-registration-paths"><div><h4>${t('Captain-led team application','已有团队：由队长提交申请')}</h4><p>${t('Prepare a team profile, representative projects, member responsibilities, application interests and technical strengths. Captains may organize existing collaborators or cross-project teams.','准备团队简介、代表项目、成员分工、应用场景与技术方向。队长可召集已有协作者，也可组织跨专业、跨项目团队。')}</p></div><div><h4>${t('Individual registration & teammate matching','个人报名：寻找队友后自由组队')}</h4><p>${t('Provide your skills, experience, representative work and teammate preferences. Find complementary collaborators, form a team, then confirm registration.','提交个人能力、经验、代表项目和组队意向，寻找互补队友，自由组合成队后确认报名。')}</p></div></div>
        <div class="event-registration-notice"><strong>${t('Registration · coming soon','报名与组队 · 稍后开始')}</strong><p>${t('Registration and team formation are not open yet. The organizing committee will announce dates, entry channels, selection arrangements and the platform calendar through the event website.','报名与组队尚未开放。报名时间、正式入口、审核与入选安排及上机日历，由组委会通过赛事官网统一公布。')}</p><div>${link('/teams/',t('Registration & team guide','参赛与组队说明'),'button')}<a class="text-link" href="https://gaac.gosim.org/" target="_blank" rel="noopener">${t('Event website','赛事官网')} gaac.gosim.org ${arrow}</a></div></div>`,false)}
        ${step('schedule','04',t('How does the competition work?','比赛怎么进行？'),t('168 hours per team, two phases and a shared EdgePod platform.','每队 168 小时，两个阶段，统一 EdgePod 平台。'),`<p>${t('The first edition plans to select five teams to use the platform in sequence. Each team receives a 168-hour competition window. The first phase establishes engineering capability; the second evaluates all three applications.','首届计划遴选 5 队，按队依次使用平台，每队比赛时长为 168 小时。第一阶段检验基础工程能力，第二阶段评测三类应用。')}</p>        <ol class="event-schedule"><li><div class="schedule-time"><span>${t('PHASE 1','第一阶段')}</span><strong>0—30 <small>${t('hours','小时')}</small></strong><p>${t('25 formal points','正式考核 25 分')}</p></div><div><h4>${t('Build the system and verify basic engineering capability','搭建系统，检验基础与工程能力')}</h4><p>${t('Rebuild and deploy the system; verify inference and concurrency, KV/state management, scheduling, recovery, complete evidence and resource accounting.','完成系统重建与部署，验证推理与并发、KV 与状态管理、调度优化、故障恢复，以及完整证据与资源计量。')}</p><p class="schedule-tools"><strong>${t('Tools','工具要求')}</strong>${t('Open book. Codex, Claude Code and mature open-source components are permitted.','开卷，可使用 Codex、Claude Code 等开发工具及成熟开源组件。')}</p></div></li><li><div class="schedule-time"><span>${t('PHASE 2','第二阶段')}</span><strong>30—168 <small>${t('hours','小时')}</small></strong><p>${t('75 formal points','正式考核 75 分')}</p></div><div><h4>${t('Complete all three applications for independent evaluation','完成三类应用，接受独立评测')}</h4><p>${t('Deliver editable PPT, financial analysis and visualization, and Deep Research. Evaluate artifact quality, efficiency under quality constraints, and independent reproduction and evidence.','完成可编辑 PPT、财报分析与可视化、Deep Research。评估交付质量、质量约束下的效率，以及独立复现与证据。')}</p><p class="schedule-tools"><strong>${t('Tools','工具要求')}</strong>${t('Formal evaluation uses a sealed version and local DeepSeek or other approved tools. Optional platform optimization takes place offline in an isolated copy and is assessed separately.','正式评测使用封存版本及本地 DeepSeek 等获准工具；可在隔离副本中离线开展平台优化，单独提交加分验收。')}</p></div></li></ol>
        <div class="event-platform"><strong>${t('Shared hardware','统一硬件平台')}</strong><span>EdgePod · 16 × RTX PRO 6000 Max-Q · 4 × 64TB NVMe · 400GbE</span></div>
        ${link('/resources/#phase-one',t('Full examination content and tool rules','查看完整考试内容与工具边界'))}`,false)}
        ${step('scoring','05',t('How are scores and prizes awarded?','怎么评分，能获得什么？'),t('100 formal points, up to 20 bonus points and one US$10,000 team grand prize.','正式 100 分＋可选加分最高 20 分；团队大奖 10,000 美元。'),`<p>${t('The formal score assesses using agents to deliver applications. The optional bonus assesses reusable engineering improvements to the platform itself. The same application result cannot earn duplicate credit.','正式分评估使用智能体完成应用的能力，可选加分评估对平台本身的可复用工程改进；同一次应用质量、Token 或成本成绩不重复加分。')}</p>        <div class="event-score-summary"><div><strong>100<span>${t('formal points','正式分')}</span></strong><p>${t('Phase 1: 25 + three applications × 25','第一阶段 25 分＋三类应用各 25 分')}</p></div><div><strong>+20<span>${t('maximum optional bonus','可选加分上限')}</span></strong><p>${t('One cap across the event. Not 20 per application.','全赛合计上限，并非每类应用各加 20 分。')}</p></div></div>
        <div class="event-score-detail"><h4>${t('How each 25-point application is scored','每类应用的 25 分如何构成')}</h4><dl><div><dt>${t('Quality','质量')}</dt><dd>15 ${t('points','分')}</dd></div><div><dt>${t('Efficiency under quality constraints','质量约束下的效率')}</dt><dd>6 ${t('points','分')}</dd></div><div><dt>${t('Independent reproduction & evidence','独立复现与证据')}</dt><dd>4 ${t('points','分')}</dd></div></dl></div>
        <div class="event-prize-note"><h4>${t('One team grand prize: US$10,000','团队大奖 1 名，奖金 10,000 美元')}</h4><p>${t('Teams meeting formal qualification, quality, safety and evidence requirements compete on their combined formal score and optional platform bonus, up to 120 points. Skipping platform optimization does not reduce the formal score.','通过正式考核资格、质量、安全与证据要求的队伍，按正式分与可选平台优化分的综合成绩参与评选，最高 120 分。不做平台优化不扣正式分。')}</p></div>
        ${link('/resources/',t('Full scoring framework and review principles','查看完整评分框架与评审原则'))}`,false)}
        ${step('after','06',t('What opportunities follow the event?','比赛结束后有哪些机会？'),t('Open-source maintenance, research, training and matching enterprise projects.','开源维护、研究与培训，以及匹配的企业项目。'),`<p>${t('The committee plans the following work during the 90 days after all teams finish, with continuing maintenance afterward. Cooperation depends on actual contribution, scenario fit and partner agreements.','组委会计划在全部队伍完成比赛后的 90 天内推进以下工作，并继续维护相关成果。后续合作按实际贡献、场景匹配与各方约定推进。')}</p>        <ol class="event-after-plan"><li><span>${t('Days 1–30','赛后 1—30 天')}</span><div><h4>${t('Review and independently reproduce the outputs','整理成果，开展独立复现')}</h4><p>${t('Review open-source materials, collect evaluation issues, assign maintainers and improve Benchmark tasks and metrics.','审查开源材料、汇总评测问题、明确维护分工，共建 Benchmark 任务与指标。')}</p></div></li><li><span>${t('Days 31–60','赛后 31—60 天')}</span><div><h4>${t('Continue testing and organize enterprise trials','持续测试，开展企业试用')}</h4><p>${t('Use the Testbed for further testing, joint research, white papers, specification drafts, courses and practical training.','在 Testbed 继续测试，推进联合研究、白皮书与规范草案，开展课程与实训。')}</p></div></li><li><span>${t('Days 61–90 and beyond','赛后 61—90 天及以后')}</span><div><h4>${t('Advance pilots and agreed enterprise projects','推进试点验收与企业项目')}</h4><p>${t('Improve reference solutions and training, and connect suitable teams with scenario development, deployment, integration and ongoing operations.','迭代参考方案与课程，对接场景开发、部署集成与持续运维合作。')}</p></div></li></ol>
        ${link('/ecosystem/',t('Full post-event cooperation plan','查看完整赛后合作计划'))}`,false)}
      </ol></div></section>
      <section class="partner-outreach" id="cooperation" aria-labelledby="partner-outreach-title"><div class="partner-outreach-heading"><h2 id="partner-outreach-title">${t('Sponsorship & cooperation','赞助与合作')}</h2></div>
        <div class="event-cooperation-list">${[
          ['partners',t('Sponsors & technology partners','赞助商与技术资源伙伴'),t('Contribute funding, compute, storage, networking, tools or engineering support. Agree on scope, delivery milestones, resource reports and technical exchanges.','提供资金、算力、存储网络、工具或工程支持，约定支持范围、交付节点、资源使用报告与成果交流。'),t('Sponsorship details','了解赞助与资源合作')],
          ['enterprise',t('Enterprise users & scenario partners','企业用户与行业场景伙伴'),t('Bring a specific business task. Define success criteria, participate in trials and independent acceptance, and explore training, deployment and enterprise projects.','提出具体业务任务，共同定义成功标准，参与试用与独立验收，进一步对接培训、部署集成与企业项目。'),t('Enterprise cooperation','了解企业场景合作')],
          ['research',t('Universities & researchers','高校与研究机构'),t('Contribute evaluation methods, joint research, white papers, courses or practical training, with outputs and milestones agreed by the partners.','参与评测方法、联合研究、白皮书、课程与实训，按实际贡献和合作约定推进。'),t('Research & education','了解研究与教育合作')]
        ].map(v=>`<div><h3><i class="gaac-icon gi-${['handshake','building','graduation-cap'][['partners','enterprise','research'].indexOf(v[0])]}" aria-hidden="true"></i>${v[1]}</h3><p>${v[2]}</p>${link('/'+v[0]+'/',v[3])}</div>`).join('')}</div>
      </section>
      <div class="event-home-end"><a href="#about">${t('Back to event overview','返回赛事介绍')} ↑</a>${link('/challenge/',t('More event details & FAQ','更多赛事说明与常见问题'))}</div>
    </div>`;
  }
  function challenge(){return pageHero(t('GAAC / COMPETITION OVERVIEW','GRAND AGENTIC AI CHALLENGE / 赛事介绍'),t('Grand Agentic<br><em>AI Challenge</em>','智能体<br><em>大奖赛</em>'),t('A real-application competition that connects application needs, agent construction, inference and infrastructure optimization. Each team has 168 hours, two phases, and three required applications.','以真实应用连接需求理解、智能体搭建、推理与基础设施优化。每队 168 小时、两个阶段、三类应用全部必做。'),link('/teams/',t('Registration & team formation','报名与组队'),'button'))+subLayout([['goals',t('Competition goals','赛事目标')],['format',t('Two phases','两个阶段')],['applications',t('Three applications','应用场景')],['platform',t('Shared platform','统一平台')],['prize',t('Grand prize','团队大奖')],['faq',t('FAQ','常见问题')]],
    article('goals',t('Make open-source systems deliver real work.','从产业需求出发，形成实际交付能力。'),p('Enterprise adoption requires clear evidence of application results, reliability, cost, deployment and ongoing maintenance. GAAC connects application teams, technical layers, open-source projects and enterprise needs through shared conditions and independent evaluation.','企业采用智能体，需要看清应用效果、可靠性、成本，以及团队能否部署和持续维护。GAAC 通过统一环境、真实任务与独立评估，连接应用团队、分层技术能力、开源项目和企业需求。')+rows([[t('Verify deployable full-stack solutions','验证可交付的开源全栈方案'),t('Combine applications, agents, model serving, state and infrastructure into runnable, reproducible and maintainable reference systems.','让应用、Agent、模型服务、状态管理与 Infra 协同，形成可运行、可复现、可持续维护的参考组合。')],[t('Improve an industry Benchmark together','共同完善产业应用 Benchmark'),t('Evaluate user experience and technical capability, then improve tasks, metrics and acceptance methods through observed issues.','从用户体验与技术能力两方面评估，通过实测问题持续改进任务、指标和验收标准。')],[t('Create continuing collaboration','形成持续合作'),t('Carry outputs into a Testbed, joint research, white papers and specification proposals, enterprise training and scenario projects.','以 Testbed 承接成果，连接联合研究、白皮书与规范建议、企业培训和场景项目。')]]))+
    article('format',t('Two phases in 168 hours.','168 小时，分别检验底座与应用。'),phases()+notice(t('Formal evaluation uses a sealed version. Platform improvements run offline in an isolated copy under uniform quotas, are accepted separately, and never overwrite or backfill formal results.','正式评测版本保持封存；平台优化在隔离副本与统一离线额度内进行，单独验收，不覆盖或回填正式成绩。'))+link('/resources/#scoring',t('See 100 + 20 scoring','查看 100＋20 双轨评分')))+
    article('applications',t('Three applications, all required.','三类应用，全部必做。'),p('Each application contributes 25 formal points and adds scenario-specific acceptance requirements to a shared layered Benchmark.','每类应用正式 25 分，在分层通用 Benchmark 上增加各自的专属验收标准。')+applications.map((a,i)=>`<section class="application-detail" id="${a.id}"><div class="application-detail-title"><span class="micro">0${i+1} / ${a.format}</span><h3>${a.name}</h3></div><p>${a.input}</p><dl><dt>${t('Deliverables','交付')}</dt><dd>${a.deliver}</dd><dt>${t('Assessment focus','考核重点')}</dt><dd>${a.quality}</dd><dt>${t('Acceptance','可用标准')}</dt><dd>${a.accept}</dd></dl></section>`).join(''))+
    article('platform',t('One EdgePod. Consistent conditions.','同一套 EdgePod，相同评测条件。'),table([t('Resource','资源'),t('Configuration','配置')],[['GPU','16 × RTX PRO 6000 Max-Q'],['NVMe','4 × 64 TB'],[t('Network','网络'),'400 GbE'],[t('Team window','每队窗口'),t('168 hours','168 小时')],[t('Scheduling','上机方式'),t('Five teams planned; sequential use of the same platform','计划遴选 5 队，按队依次使用统一平台')]])+p('Model versions, permitted tools, public practice materials and formal technical rules will be published before the event.','具体模型版本、允许工具、公开练习材料与正式技术规则，在开赛前统一发布。'))+
    article('prize',t('One team grand prize. US$10,000.','团队大奖 1 名，奖金 10,000 美元。'),p('Qualified teams that meet formal assessment, quality, safety and evidence requirements are ranked using the formal 100-point score plus the optional platform bonus, for a maximum of 120. Reviewers consider real contributions to application delivery and platform engineering.','大奖面向通过正式考核资格、质量、安全与证据要求的队伍，按正式 100 分与可选平台优化最高 20 分的综合成绩评选，合计最高 120 分。评审同时关注场景交付和平台工程的实际贡献。'))+
    article('faq',t('Questions before you join.','报名之前，你可能想了解。'),sharedFaq()+scheduleNotice()))+cta();}
  function teams(){return `<div class="wrap"><section class="registration-pending glass-surface" aria-labelledby="registration-title"><div class="registration-pending-icon" aria-hidden="true"><i class="gaac-icon gi-calendar-clock"></i></div><p class="registration-pending-label">${t('Registration & team formation','报名参赛与组队')}</p><h1 id="registration-title">${t('Coming soon','稍后开始')}</h1><p class="registration-pending-copy">${t('Registration and team formation are not open yet. The organizing committee will announce opening dates and how to participate.','报名与组队尚未开放。开放时间及参与方式，将由赛事组委会统一公布。')}</p><div class="registration-pending-actions">${link('/resources/',t('View format & scoring','查看赛制与评分'),'button')}${link('/',t('Back to event overview','返回赛事首页'))}</div></section></div>`;}

  function partners(){return pageHero(t('GAAC / SPONSORS & TECHNOLOGY PARTNERS','GAAC / 赞助商与技术资源伙伴'),t('Sponsorship<br><em>& technical resources</em>','赛事赞助<br><em>与技术资源合作</em>'),t('Contribute funding, compute, storage, networking, tools and engineering to the event and continuing Testbed work.','通过资金、算力、存储网络、工具和工程支持，参与赛事与持续 Testbed 建设。'),link('/involve/?role=partner#partners',t('Prepare a partnership brief','准备赞助与资源合作资料'),'button'))+subLayout([['support',t('Ways to support','支持方式')],['value',t('Partner value','参与价值')],['long-term',t('Continuing cooperation','长期合作')],['independence',t('Independent evaluation','独立评估')]],
    article('support',t('Bring resources that help teams deliver.','提供支撑真实交付的资源。'),rows([[t('Funding','资金支持'),t('Support competition delivery and agreed continuing verification, coordination or maintenance work.','支持赛事执行及约定的持续验证、协调和维护工作。')],[t('Compute, storage & networking','算力、存储与网络'),t('Contribute compute, hosting, storage, networking and platform operations for the shared environment.','提供算力、托管、存储网络与统一平台运维支持。')],[t('Tools & engineering','工具与工程支持'),t('Help integrate, test, adapt and operate components under agreed competition and Testbed conditions.','按约定条件提供组件集成、测试、技术适配与运行支持。')],[t('Continuing Testbed resources','持续 Testbed 资源'),t('Keep reference solutions testable, reproducible and maintainable after the competition.','支撑赛后参考方案的持续测试、复现与维护。')]]))+
    article('value',t('Agree on visible, verifiable outcomes.','以可核对成果体现合作价值。'),rows([[t('Agreed brand visibility','约定的品牌展示'),t('Present partner contributions through agreed event and outcome communication.','按约定在赛事与成果传播中呈现合作贡献。')],[t('Resource & outcome reports','资源使用与成果报告'),t('Review actual use, deliverables and continuing verification at agreed milestones.','在约定节点回顾实际资源使用、交付成果和后续验证。')],[t('Adaptation feedback','技术适配反馈'),t('Understand behavior, limitations and improvement opportunities under actual application workloads.','了解技术在真实应用负载中的表现、边界与改进机会。')],[t('Enterprise & developer exchanges','面向企业和开发者的交流'),t('Share results and develop matching technology and scenario cooperation.','围绕成果交流，连接匹配的技术与场景合作。')]]))+
    article('long-term',t('Support for reusable post-event outputs.','支持可复用的赛后公共成果。'),p('Competition outputs can become reusable full-stack packages, industry Benchmarks, white papers, specification proposals, training and enterprise cooperation resources. Define the support scope, delivery milestones and later verification plan with the organizing committee.','赛事成果可沉淀为开源全栈方案、产业 Benchmark、白皮书、规范建议、培训与企业合作资源。与组委会对齐支持范围、交付节点和后续验证计划。')+link('/ecosystem/',t('Explore the 90-day plan','了解赛后 90 天计划')))+
    article('independence',t('Shared conditions. Independent conclusions.','统一条件，独立评价。'),notice(t('Resource sponsorship does not change assessment standards or technical conclusions. Rules and resource boundaries are published before the event, and success and failure records are retained for review.','资源赞助不改变评估标准或技术结论。规则与资源边界赛前公布，完整保留成功与失败记录，成绩支持复核。'))))+cta();}
  function enterprise(){return pageHero(t('GAAC / ENTERPRISE USERS & SCENARIO PARTNERS','GAAC / 企业用户与行业场景伙伴'),t('Enterprise scenarios<br><em>& project cooperation</em>','企业场景<br><em>与项目合作</em>'),t('Define success, test results, build internal capabilities, and explore direct enterprise cooperation with teams and open-source partners.','共同定义成功标准、检验结果、建设内部能力，并与参赛团队、开源维护者和生态伙伴开展直接企业项目合作。'),link('/involve/?role=enterprise#enterprise',t('Prepare a scenario brief','准备企业场景资料'),'button'))+subLayout([['start',t('Start with one task','从一项任务开始')],['journey',t('Participation journey','参与路径')],['projects',t('Project cooperation','项目合作')],['capability',t('Training & acceptance','培训与验收')]],
    article('start',t('Make the business task specific.','把真实业务任务讲清楚。'),rows([[t('Current workflow','现有流程'),t('Describe the task, pain points, current baseline, expected result and domain owner.','说明任务、痛点、现有基线、预期结果和领域负责人。')],[t('Acceptance criteria','成功与验收标准'),t('Define output quality and usefulness, then examine reliability, complete cost and team handover.','共同定义输出质量与可用标准，再看可靠性、完整成本和团队接管。')],[t('Authorized data','数据授权边界'),t('Identify which materials can be used and what must remain private or controlled.','明确哪些资料可以使用，哪些数据须保持私有或受控。')]]))+
    article('journey',t('Co-create, try, learn, and validate.','共创标准，试用方案，建设能力。'),rows([[t('Benchmark & criteria co-creation','Benchmark 与验收共创'),t('Contribute real requirements and reusable application and technical acceptance methods.','提出真实需求，共同定义可复用的应用与技术验收方法。')],[t('Sandbox trials','沙箱试用'),t('Try suitable solutions and review real outputs and failure modes with the domain owner.','试用匹配方案，与领域负责人一起检查实际输出与失败情况。')],[t('Practical team training','团队实操培训'),t('Help business, development, IT and security teams define needs, deploy, use, assess and take over agentic systems.','帮助业务、开发、IT 与安全团队学习定义需求、部署、使用、评估和接管智能体。')],[t('Scenario pilots','场景适配与试点'),t('Adapt workflows, integrate approved systems and data, and evaluate actual business results.','适配应用流程、集成获准系统与数据，以实际业务结果验收。')]]))+
    article('projects',t('Direct cooperation around clear needs.','围绕明确需求开展直接企业项目合作。'),p('Matching projects may include solution assessment, scenario development, deployment and integration, pilot delivery and operations. The parties agree on scope, resources, deliverables and acceptance goals for each project.','对于匹配需求，可开展方案评估、场景开发、部署集成、试点交付与运维合作；由参与各方按项目范围、资源、交付和验收目标具体约定。'))+
    article('capability',t('Useful results, and people who can take over.','结果可用，也让团队真正会用。'),p('Application scenarios check editable PPT delivery, financial figures and definitions, and research claims and evidence. Training turns those methods into enterprise capabilities. Reusable outcomes feed into open-source packages, teaching and industry templates within permission boundaries.','应用场景分别核验 PPT 可编辑交付、财报数字与口径、研究主张与证据。培训把这些方法转为内部能力；在授权边界内，可复用经验回到开源参考包、课程与行业模板。')))+cta();}
  function research(){return pageHero(t('GAAC / UNIVERSITIES & RESEARCH INSTITUTIONS','GAAC / 高校与研究机构'),t('Research cooperation<br><em>& practical education</em>','研究合作<br><em>与课程实训</em>'),t('Contribute evaluation methods, joint research, white papers, specification proposals, courses and practical training.','围绕评测方法、联合研究、白皮书、规范建议、课程与实训，参与持续共建。'),link('/involve/?role=research#research',t('Prepare a research proposal','准备研究与课程共建资料'),'button'))+subLayout([['methods',t('Research & methods','研究与评测方法')],['outputs',t('Shared knowledge','知识与规范成果')],['education',t('Courses & training','课程与实训')],['collaboration',t('How to collaborate','合作方式')]],
    article('methods',t('Study user experience and technical capability.','把用户体验与技术能力一起研究。'),rows([[t('Industry Benchmark','产业 Benchmark'),t('Help define and calibrate reusable user, application and technical evaluation tasks, metrics and acceptance methods.','共建可复用的用户、应用与技术评测，持续校准任务、指标和验收方法。')],[t('Joint experiments','联合研究'),t('Use competition evidence and the continuing Testbed to examine real systems, reproduction and scenario validity.','基于赛事证据与持续 Testbed，研究真实系统、复现与场景评测有效性。')],[t('Platform engineering','平台工程研究'),t('Study reusable capabilities across definition, design, construction, verification, release/operation and evolution/retirement.','围绕定义、设计、构建、验证、发布运行、演进退役，研究可复用平台能力。')]]))+
    article('outputs',t('White papers and reports based on competition evidence.','基于实测证据编写白皮书与报告。'),p('Co-author white papers, technical reports and cases; develop specification drafts and standard proposals; participate in public review and validation. Results are shared according to actual contribution, licenses and agreed data permissions.','围绕实测证据联合编写白皮书、技术报告与案例，形成规范草案和标准建议，参与公开评审与验证；按实际贡献、许可与数据授权约定成果范围。'))+
    article('education',t('Teach what teams can demonstrate.','用真实交付成果开展课程与实训。'),p('Co-create courses and practical exercises for enterprise users, developers and learners. Cover defining requirements, deploying, using, assessing and taking over agents, with real artifacts and verifiable outcomes.','共同开发面向企业用户、开发者与学习者的课程和实训，覆盖需求定义、部署、使用、评估与接管，以真实工件和可核验结果体现学习成果。'))+
    article('collaboration',t('Work from a concrete contribution.','从一项具体贡献开始。'),p('Propose a method, research question, white-paper contribution, course or practical training task. Agree on owners, available data, outputs and milestones with the organizing committee and relevant partners.','提出评测方法、研究问题、白皮书内容、课程或实训任务，与组委会及伙伴明确负责人、数据、成果范围和里程碑。')+link('/ecosystem/',t('See the continuing collaboration plan','查看持续合作计划'))))+cta();}
  function ecosystem(){return pageHero(t('GAAC / POST-EVENT INDUSTRY COLLABORATION','GAAC / 赛后产业合作'),t('Post-event plans<br><em>& industry cooperation</em>','赛后计划<br><em>与产业合作</em>'),t('After all teams complete the event, a 90-day plan connects reproduction, continuous testing, enterprise co-creation and continuing maintenance.','在全部队伍完成比赛后的 90 天内，分步推进成果复现、持续测试、企业共创，并继续维护开源与评测资产。'),link('/involve/',t('Find a collaboration path','选择共建方式'),'button'))+subLayout([['roadmap',t('90-day plan','赛后 90 天计划')],['work',t('Long-term work','长期共建工作')],['testbed',t('Continuing Testbed','持续 Testbed')],['publication',t('Publication & permissions','成果与授权')]],
    article('roadmap',t('Work planned after all teams finish.','全部队伍完赛后的工作安排。'),roadmapRows())+
    article('work',t('Five ways to keep building together.','五类可以共同推进的长期工作。'),rows([[t('Industry Benchmark','产业 Benchmark'),t('Enterprises, developers and researchers jointly define reusable user, application and technical evaluation, and continuously calibrate tasks, indicators and acceptance.','与企业、开发者和研究者共同定义可复用的用户、应用与技术评测，持续校准任务、指标与验收方法。')],[t('White papers & standard cooperation','白皮书与标准合作'),t('Co-author evidence-based white papers, reports and cases; form specification drafts and standard proposals; join public review and validation.','围绕实测证据联合编写白皮书、报告与案例，形成规范草案和标准建议，参与公开评审与验证。')],[t('Open-source full-stack solutions','开源全栈解决方案'),t('Integrate applications, agents, model serving and infrastructure into deployable, handover-ready packages and scenario templates.','整合应用、Agent、模型服务与 Infra，形成可部署、可接手的参考包和场景模板，持续维护与适配组件。')],[t('Enterprise user training','企业用户培训'),t('Develop courses and practical training so business, development, IT and security teams can define, deploy, use, assess and take over agents.','共建课程和实训，帮助业务、开发、IT 与安全团队定义需求、部署、使用、评估与接管智能体。')],[t('Direct enterprise projects','直接企业项目合作'),t('Cooperate on solution assessment, scenario development, deployment, integration, pilot delivery and operations around agreed project scope and acceptance.','围绕明确需求开展方案评估、场景开发、部署集成、试点交付与运维合作，具体约定范围和验收目标。')]]))+
    article('testbed',t('Keep systems testable after the event.','让方案在赛后继续接受真实检验。'),p('The Testbed carries competition outputs into repeated testing, reproduction, technology adaptation, joint research and enterprise trials. Issues feed back into the Benchmark, architecture, open-source projects and courses.','Testbed 承接赛事成果，开展持续测试、复现、技术适配、联合研究和企业试用，将问题回流至 Benchmark、参考架构、开源项目与课程。'))+
    article('publication',t('Share reusable work within clear boundaries.','在清楚的授权边界内复用成果。'),p('Releasable application and platform code, configurations, methods and reproduction materials are published under agreed licenses and permissions. Enterprise data, trade secrets and unauthorized content remain governed by their own boundaries. Follow-up cooperation depends on contribution, scenario fit and partner agreements.','可公开的应用与平台改进代码、参考配置、方法和复现材料，按约定许可与授权发布。企业数据、商业机密和未授权内容按各自边界管理，后续合作依据贡献、场景匹配与双方约定推进。')))+cta();}
  function resources(){return pageHero(t('GAAC / EXAMINATION & ASSESSMENT','GAAC / 考试内容与评估标准'),t('100 formal points.<br><em>Up to 20 more for the platform.</em>','正式考核 100 分。<br><em>平台优化最高加 20 分。</em>'),t('Use agents to complete real applications, and optionally improve the agentic platform itself. The combined maximum is 120 for teams meeting the formal qualifying requirements.','正式分评用智能体完成真实应用的能力；可选加分评平台本身的可复用工程改进。通过主赛合格条件的队伍，按两项合计评选，最高 120 分。'),`<button class="button ghost" data-action="print">${t('Print / save as PDF','打印 / 保存为 PDF')}${arrow}</button>`)+subLayout([['scoring',t('Two scoring tracks','双轨评分')],['phase-one',t('Phase one','第一阶段')],['application-score',t('Application scoring','应用评分')],['perspectives',t('User & technical views','用户与技术视角')],['platform-bonus',t('Platform bonus','平台优化加分')],['principles',t('Review principles','共同评审原则')],['materials',t('Current material','公开介绍原文')]],
    article('scoring',t('Two kinds of engineering. Distinct evidence.','两类工程能力，分别提供证据。'),scoringTracks()+notice(t('The platform bonus is capped at 20 across the entire competition, not per application. It is optional. Qualified teams compete for one US$10,000 team grand prize using the combined result, up to 120.','平台加分全赛合计最高 20 分，并非每类应用 20 分；选择不做不扣正式分。合格队伍按最高 120 分的综合成绩，参与 1 名、10,000 美元团队大奖的评选。')))+
    article('phase-one',t('Hours 0–30: foundation and engineering.','0—30 小时：基础与工程能力。'),p('Phase one contributes 25 formal points. It is open book and permits Codex, Claude Code and mature open-source components. Build the environment needed for application evaluation.','第一阶段正式 25 分，开卷，可使用 Codex、Claude Code 等工具和成熟开源组件，为应用考核准备运行环境。')+rows([[t('Rebuild & deploy','系统重建与部署'),t('Build a runnable system from a clean environment that another person can take over.','从干净环境搭建可运行、可交接的系统。')],[t('Inference & concurrency','推理服务与并发能力'),t('Provide stable model serving with resource quotas, concurrency and cancellation.','稳定提供模型服务，处理资源配额、并发与取消。')],[t('KV & state','KV 与状态管理'),t('Verify reuse, persistence, recovery, version compatibility and isolation.','验证缓存复用、状态保存恢复、版本兼容与隔离。')],[t('Inference & scheduling','推理与调度优化'),t('Compare the actual effect and cost of different runtime configurations.','比较不同运行配置在实际负载下的效果与代价。')],[t('Reliability & recovery','可靠性与恢复'),t('Recover and close out correctly after tool failure or service interruption.','在工具失败、服务中断等情况下正确恢复和收尾。')],[t('Evidence & measurement','完整证据与资源计量'),t('Reconcile tasks, model calls, tools, artifacts, time and cost.','让任务、模型、工具、工件、时间与成本能够对应核验。')]]))+
    article('application-score',t('Hours 30–168: three applications, 25 each.','30—168 小时：三类应用，各 25 分。'),p('Editable PPT, financial analysis and visualization, and Deep Research are all required. Each combines a common layered Benchmark with scenario-specific acceptance.','可编辑 PPT、财报分析与可视化、Deep Research 全部必做。共用分层通用 Benchmark，再加入各自专属验收。')+table([t('Per-application assessment','每类应用评估项'),t('Points','分值'),t('Public criteria','公众评估标准')],[[t('Quality','质量'),'15',t('Correct results and usable artifacts; general user experience and quality of agent execution in the actual task.','结果正确、工件可用，兼顾通用用户体验和 Agent 执行本题的实际质量。')],[t('Efficiency under quality constraints','质量约束下的效率'),'6',t('End-to-end time, tokens, complete running cost, GPU efficiency and capacity meeting service objectives, for qualified tasks.','在合格任务前提下，比较端到端时间、Token、完整运行成本、GPU 效率和服务目标下的承载能力。')],[t('Independent reproduction & evidence','独立复现与证据'),'4',t('Independent rebuild, rerun and review, with consistent artifacts, sources, traces and measurements.','能够独立重建、复跑与复核，工件、来源、运行轨迹和计量记录完整一致。')]])+link('/challenge/#applications',t('Read scenario-specific deliverables','查看各场景交付与可用标准')))+
    article('perspectives',t('Evaluate what users experience and what systems do.','既看用户体验，也看实际技术表现。'),rows([[t('User perspective','用户视角'),t('Intent understanding, ease of use, feedback and waiting, editing and control, security and privacy, continuity and understandable results. Add PPT editability, financial figures and definitions, and research claims and evidence.','通用体验包括意图理解、易用性、反馈与等待、修改和控制、安全隐私、连续任务及结果可理解性；专属质量分别检查 PPT 可编辑性、财报数字口径和研究主张证据。')],[t('Technical perspective','技术视角'),t('Planning, tools, state and recovery during actual tasks; scenario-level inference, KV, scheduling, storage, token efficiency and cost per qualified task. Phase-one benchmark results do not substitute for application results.','检查本题规划、工具调用、状态与恢复，以及推理、KV、调度、存储的场景表现、Token 效率和单位合格任务成本。第一阶段基础跑分不替代应用实际表现。')]]))+
    article('platform-bonus',t('Engineering Agentic Systems: up to 20 points.','Engineering Agentic Systems：最高加 20 分。'),p('Teams may implement reusable platform improvements during phase two. Using the ASE lifecycle in the Agentic Software Engineering Industry White Paper, assess the platform across six stages.','团队可在第二阶段对平台本身实现可复用改进。依据《智能体软件工程产业白皮书》的 ASE 全生命周期，从六个阶段评估平台能力。')+`<div class="ase-stages">${[t('Definition','定义'),t('Design','设计'),t('Construction','构建'),t('Verification','验证'),t('Release & operation','发布与运行'),t('Evolution & retirement','演进与退役')].map((v,i)=>`<div><span class="micro">0${i+1}</span><strong>${v}</strong></div>`).join('')}</div>`+p('Assess specifications and context, controlled execution, versioned delivery, test evidence, operational governance and continuous evolution. Improvements require real baseline changes, runnable implementation, independent verification and reuse evidence.','评估规范与上下文、受控执行、版本化交付、测试证据、运行治理和持续演进。改进须有相对基线的实际变化、可运行实现、独立验证与复用证据。')+notice(t('Keep the formal evaluation version sealed. Optimize only in an isolated copy under uniform offline quotas, using public development material. Accept results separately. A repair to one PPT, workbook or report remains application delivery, and the same quality, token or cost result cannot be counted twice.','正式评测版本保持封存；仅在隔离副本与统一离线额度内，使用公开开发材料进行优化，结果单独验收。修补单份 PPT、工作簿或报告仍属场景交付，同一次质量、Token 或成本成绩不重复加分。')))+
    article('principles',t('Quality, safety, evidence and independence.','质量、安全、证据与独立评价。'),rows([[t('Quality before efficiency','先过质量，再看效率'),t('Complete task acceptance is the foundation. Incorrect results do not earn efficiency credit for apparent speed or low usage.','完整任务验收是基础；错误结果造成的表面提速或低消耗，不能获得相应效率收益。')],[t('Safety & authenticity','安全与真实性'),t('Authorization, isolation, privacy, sources and evidence are checked. Serious violations follow the formal charter.','核查授权、隔离、隐私、来源与证据，严重违规按正式章程处理。')],[t('Independent verification','结果可独立验证'),t('Combine artifact inspection, recalculation, source checks, running tests and independent reproduction. Results support review.','结合工件检查、数字复算、来源核验、运行测试与独立复现，成绩支持复核。')],[t('Uniform conditions','条件统一，评价独立'),t('Publish rules and resource boundaries before the event, retain success and failure records, and keep sponsorship independent of conclusions.','规则与资源边界赛前公布，保留成功与失败记录；资源赞助不改变技术结论。')]])+scheduleNotice())+
    article('materials',t('Current public event introduction.','当前公开赛事介绍。'),`<a class="resource-row" href="/assets/GAAC_Event_Overview_2026-11-02.txt" download><span class="file-type mono">TXT</span><div><h3>${t('Grand Agentic AI Challenge · public introduction','Grand Agentic AI Challenge · 赛事招募与产业合作')}</h3><p>${t('Current Chinese source · updated 2 November 2026','当前中文原文 · 2026 年 11 月 2 日更新')}</p></div><span class="arrow">↓</span></a>`+p('This page publishes the examination direction and assessment framework. Detailed rubrics, qualification requirements, permitted tools, task arrangements and appeals will be published through unified technical rules.','本页公开考试方向和评估框架；详细评分量规、资格要求、允许工具、正式任务安排与申诉程序，将通过统一技术规则发布。')+`<details class="faq"><summary>${t('Archived material','历史资料')}</summary><p>${t('The V1.3 pitch deck predates this introduction and is retained as an archive, not the current scoring or registration rules.','V1.3 路演提案早于本次介绍，仅作归档，不作为现行评分与报名规则。')}</p><a class="text-link" href="/assets/OAIC_Challenge_Pitch_Executive_V1.3.pptx" download>${t('Archived V1.3 deck','下载历史 V1.3 提案')} ↓</a></details>`));}
  function involve(){return pageHero(t('GAAC / REGISTRATION & COOPERATION','GAAC / 报名组队与产业合作'),t('Registration<br><em>& cooperation guide</em>','报名与合作<br><em>参与方式</em>'),t('Captains can apply as teams; individuals can register and find teammates. Sponsors, enterprise users, universities and researchers can contribute resources, needs and methods.','队长提交组队申请，个人可自由报名并寻找队友；赞助商、企业用户、高校与研究机构可带来资源、需求和方法。'))+`<div class="wrap involve-content"><section id="teams" class="participation-block"><div>${eyebrow(t('01 / PARTICIPANTS','01 / 参赛与寻找队友'))}<h2>${t('Registration & teams · coming soon','报名与组队 · 稍后开始')}</h2><p>${t('Registration and team formation are not open yet. Opening dates and participation channels will be announced by the organizing committee.','报名与组队尚未开放，开放时间及参与渠道将由赛事组委会统一公布。')}</p></div><div class="participation-actions">${link('/teams/',t('Read the team guide','查看参赛与组队说明'),'button')}<button class="role-choice" data-action="role" data-role="team">${t('Prepare my participation brief','准备我的参赛资料')}${right}</button></div></section><section id="partners" class="participation-block"><div>${eyebrow(t('02 / SPONSORS & RESOURCES','02 / 赞助与技术资源'))}<h2>${t('Support the event and its shared assets.','支持赛事与共享资源。')}</h2><p>${t('Describe funding, compute, storage, networking, tools, engineering or maintenance resources you can contribute. Agree on scope, milestones and later verification with the organizing committee.','说明可提供的资金、算力、存储网络、工具、工程或维护资源，以及希望参与的成果交流方向；与组委会对齐支持范围、交付节点和验证计划。')}</p></div><div class="participation-actions">${link('/partners/',t('Explore sponsorship','了解赞助与资源合作'),'button')}<button class="role-choice" data-action="role" data-role="partner">${t('Prepare a partner brief','准备合作资料')}${right}</button></div></section><section id="enterprise" class="participation-block"><div>${eyebrow(t('03 / ENTERPRISE SCENARIOS','03 / 企业场景与解决方案'))}<h2>${t('Start with one concrete business task.','从一项具体业务任务开始。')}</h2><p>${t('Describe the current workflow, expected outcome, data permissions and domain owner. Co-create Benchmark and acceptance methods, then explore sandbox trials, training and enterprise project cooperation.','说明现有流程、预期结果、数据授权边界与领域负责人。先共创 Benchmark 和验收标准，再开展沙箱试用、团队培训与企业项目对接。')}</p></div><div class="participation-actions">${link('/enterprise/',t('Explore enterprise cooperation','了解企业参与路径'),'button')}<button class="role-choice" data-action="role" data-role="enterprise">${t('Prepare a scenario brief','准备场景资料')}${right}</button></div></section><section id="research" class="participation-block"><div>${eyebrow(t('04 / RESEARCH & EDUCATION','04 / 研究与教育'))}<h2>${t('Contribute methods, research or teaching.','以方法、研究和教学参与共建。')}</h2><p>${t('Propose evaluation methods, joint research, white-paper contributions, courses or practical training. Set outputs and milestones with the relevant partners.','提出评测方法、联合研究、白皮书、课程或实训方向，与相关伙伴明确成果与里程碑。')}</p></div><div class="participation-actions">${link('/research/',t('Explore research collaboration','了解研究与课程共建'),'button')}<button class="role-choice" data-action="role" data-role="research">${t('Prepare a research brief','准备研究资料')}${right}</button></div></section><section class="official-notice"><div><h2>${t('Registration and cooperation announcements','正式报名与合作公告')}</h2><p>${t('Follow the event website for registration, team formation, sponsorship and enterprise cooperation channels. Dates, selections and platform windows are announced by the organizing committee.','报名、组队、赞助与企业合作入口，请关注赛事官网发布。时间、入选安排和上机日历由组委会统一公告。')}</p></div>${official()}</section><section class="involve-grid" id="prepare"><div><h2>${t('Prepare your materials.','先把资料准备清楚。')}</h2><p>${t('Use this brief builder to organize your contribution, representative work, desired collaborators and first milestone. Download or copy the brief, then follow the official registration or cooperation announcement.','整理你的贡献、代表项目、希望补充的能力和首个里程碑。可下载或复制资料，再按正式报名或合作公告提交。')}</p>${notice(t('This tool prepares a downloadable brief; it does not submit a registration.','这里用于准备可下载资料，不会自动提交报名。'))}</div><div><form id="brief-form"><div class="field"><label for="role">${t('Participation path','参与身份')}</label><select id="role" name="role"><option value="team">${t('Team captain / individual participant','队长组队 / 个人参赛')}</option><option value="partner">${t('Sponsor / technology partner','赞助商 / 技术资源伙伴')}</option><option value="enterprise">${t('Enterprise / scenario partner','企业用户 / 场景伙伴')}</option><option value="research">${t('Research / education partner','研究 / 教育伙伴')}</option></select></div><div class="field"><label for="contribution">${t('Profile, work and participation interests','简介、代表项目与参与意向')} *</label><textarea id="contribution" name="contribution" required maxlength="3000" placeholder="${t('Your background, contribution, current collaborators, and skills or support you need.','你的经历、可贡献内容、已有协作者，以及希望补充的能力或支持。')}"></textarea></div><div class="field"><label for="milestone">${t('First deliverable or next step','首项交付或下一步计划')} *</label><input id="milestone" name="milestone" required maxlength="500" placeholder="${t('A concrete outcome and a realistic time window.','一项具体成果与合理时间窗口。')}"></div><button class="button" type="submit">${t('Create my brief','生成我的资料')}${arrow}</button></form><div id="brief-output" aria-live="polite"></div></div></section></div>`;}
  return {home,challenge,teams,partners,enterprise,research,ecosystem,resources,involve};
}
